How can I create a truth table for the Boolean "OR" symbol in C++? Can you provide me with a code snippet to generate the truth table for "OR" using the following variables:
bool a = true;
bool b = false;
Here's the code snippet to generate the truth table for "OR" using the variables a and b:
#include <iostream>
using namespace std;
int main() {
  bool a = true;
  bool b = false;
  cout << "Truth Table for OR Symbol:" << endl;
  cout << "--------------------------" << endl;
  cout << "   A     |     B     |  A OR B" << endl;
  cout << "--------------------------------" << endl;
  cout << "  " << a << "  |  " << b << "  |    " << (a || b) << endl;
  a = true;
  b = true;
  cout << "  " << a << "  |  " << b << "  |    " << (a || b) << endl;
  a = false;
  b = true;
  cout << "  " << a << "  |  " << b << "  |    " << (a || b) << endl;
  a = false;
  b = false;
  cout << "  " << a << "  |  " << b << "  |    " << (a || b) << endl;
  return 0;
}

