To solve this system of equations, we can use matrix algebra. First, we can write the system in matrix form as Ax = b, where A is the coefficient matrix, x is the column vector of variables (x, y, z), and b is the column vector of constants on the right-hand side of the equations. 
We can then solve for x by taking the inverse of A and multiplying both sides by it: x = A^-1 * b. 
Here's the C# code that implements this approach:
```
using System;
class Program {
    static void Main(string[] args) {
        double[,] A = {{5, 7, -3}, {3, -2, 6}, {2, 5, -4}, {4, -3, 2}, {6, 4, -5}, {7, -6, 8}};
        double[] b = {22, -5, 10, 3, -12, 11};
        double[,] A_inv = MatrixInverse(A);
        double[] x = MatrixVectorMultiply(A_inv, b);
        Console.WriteLine("x = {0}, y = {1}, z = {2}", x[0], x[1], x[2]);
    }
    static double[,] MatrixInverse(double[,] matrix) {
        int n = matrix.GetLength(0);
        double[,] inverse = new double[n, n];
        // Calculate the determinant of the matrix
        double det = MatrixDeterminant(matrix);
        // Calculate the adjugate matrix
        double[,] adjugate = MatrixAdjugate(matrix);
        // Calculate the inverse matrix by dividing the adjugate by the determinant
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                inverse[i, j] = adjugate[i, j] / det;
            }
        }
        return inverse;
    }
    static double MatrixDeterminant(double[,] matrix) {
        int n = matrix.GetLength(0);
        double det = 0;
        if (n == 1) {
            det = matrix[0, 0];
        } else if (n == 2) {
            det = matrix[0, 0] * matrix[1, 1] - matrix[0, 1] * matrix[1, 0];
        } else {
            for (int j = 0; j < n; j++) {
                double[,] submatrix = new double[n - 1, n - 1];
                for (int i = 1; i < n; i++) {
                    for (int k = 0; k < n; k++) {
                        if (k < j) {
                            submatrix[i - 1, k] = matrix[i, k];
                        } else if (k > j) {
                            submatrix[i - 1, k - 1] = matrix[i, k];
                        }
                    }
                }
                det += Math.Pow(-1, j) * matrix[0, j] * MatrixDeterminant(submatrix);
            }
        }
        return det;
    }
    static double[,] MatrixAdjugate(double[,] matrix) {
        int n = matrix.GetLength(0);
        double[,] adjugate = new double[n, n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double[,] submatrix = new double[n - 1, n - 1];
                for (int k = 0; k < n; k++) {
                    for (int l = 0; l < n; l++) {
                        if (k < i && l < j) {
                            submatrix[k, l] = matrix[k, l];
                        } else if (k < i && l > j) {
                            submatrix[k, l - 1] = matrix[k, l];
                        } else if (k > i && l < j) {
                            submatrix[k - 1, l] = matrix[k, l];
                        } else if (k > i && l > j) {
                            submatrix[k - 1, l - 1] = matrix[k, l];
                        }
                    }
                }
                adjugate[i, j] = Math.Pow(-1, i + j) * MatrixDeterminant(submatrix);
            }
        }
        return adjugate;
    }
    static double[] MatrixVectorMultiply(double[,] matrix, double[] vector) {
        int m = matrix.GetLength(0);
        int n = matrix.GetLength(1);
        double[] result = new double[m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                result[i] += matrix[i, j] * vector[j];
            }
        }
        return result;
    }
}
```
Running this code outputs the following solution:
