public class Person
{
    public string Name { get; set; }
    public List<Person> Friends { get; set; }
}
public class SocialNetworkAnalyzer
{
    public double CalculateRelationshipStrength(Person person1, Person person2)
    {
        int commonFriends = person1.Friends.Intersect(person2.Friends).Count();
        double totalFriends = person1.Friends.Count + person2.Friends.Count - commonFriends;
        return commonFriends / totalFriends;
    }
}
