                                    title TEXT,\
                                    genre TEXT,\
                                    author TEXT,\
                                    date_published INT,\
                                    average_rating REAL\
                                    );";
    rc = sqlite3_exec(db, sql_create_table, callback, 0, &zErrMsg);
    if (rc != SQLITE_OK) {
        cout << "SQL error: " << zErrMsg << endl;
        sqlite3_free(zErrMsg);
    } else {
        cout << "Table created successfully" << endl;
    }
