                                    ('Wuthering Heights', 'Romance', 'Emily Bronte', 1847, 4.1);";
    rc = sqlite3_exec(db, sql_insert_data, callback, 0, &zErrMsg);
    if (rc != SQLITE_OK) {
        cout << "SQL error: " << zErrMsg << endl;
        sqlite3_free(zErrMsg);
    } else {
        cout << "Records created successfully" << endl;
