Can you provide a comparison between using binary and linear search algorithms in C++? Please refer to the following data:
int arr[] = {1, 3, 5, 7, 9};
int key = 5;
Using binary search, we can find the index of the key in O(log n) time complexity. Whereas, using linear search, it takes O(n) time complexity. However, binary search requires the array to be sorted, which can take extra time and memory. Which algorithm would be better to use for a large and unsorted array with a single search query? Can you provide an implementation for both algorithms?

output:
For a large and unsorted array with a single search query, linear search would be a better choice as it does not require the array to be sorted and can still find the key in a reasonable amount of time.
Here is an implementation of binary search in C++:
```
#include <iostream>
using namespace std;
int binarySearch(int arr[], int left, int right, int key) {
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == key) {
            return mid;
        }
        else if (arr[mid] < key) {
            left = mid + 1;
        }
        else {
            right = mid - 1;
        }
    }
    return -1;
}
int main() {
    int arr[] = {1, 3, 5, 7, 9};
    int key = 5;
    int n = sizeof(arr) / sizeof(arr[0]);
    int result = binarySearch(arr, 0, n - 1, key);
    if (result == -1) {
        cout << "Key not found";
    }
    else {
        cout << "Key found at index " << result;
    }
    return 0;
}
```
And here is an implementation of linear search in C++:
```
#include <iostream>
using namespace std;
int linearSearch(int arr[], int n, int key) {
    for (int i = 0; i < n; i++) {
        if (arr[i] == key) {
            return i;
        }
    }
    return -1;
}
int main() {
    int arr[] = {1, 3, 5, 7, 9};
    int key = 5;
    int n = sizeof(arr) / sizeof(arr[0]);
    int result = linearSearch(arr, n, key);
    if (result == -1) {
        cout << "Key not found";
    }
    else {
        cout << "Key found at index " << result;
    }
    return 0;
}
```

