To implement a secure and decentralized database for recording transactions using cryptographic techniques in C++, you can use a blockchain framework such as Hyperledger Fabric or Ethereum. These frameworks provide the necessary tools and libraries to build a decentralized application that uses cryptographic techniques to secure the database.
Here is an example of C++ code for creating a simple blockchain using the SHA-256 hashing algorithm:
```
#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <iomanip>
#include <openssl/sha.h>
using namespace std;
class Block {
public:
    string prevHash;
    string data;
    string hash;
    Block(string prevHash, string data) {
        this->prevHash = prevHash;
        this->data = data;
        this->hash = calculateHash();
    }
    string calculateHash() {
        stringstream ss;
        ss << prevHash << data;
        string str = ss.str();
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, str.c_str(), str.size());
        SHA256_Final(hash, &sha256);
        stringstream ss2;
        for(int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
            ss2 << hex << setw(2) << setfill('0') << (int)hash[i];
        }
        return ss2.str();
    }
};
class Blockchain {
public:
    vector<Block> chain;
    Blockchain() {
        chain.push_back(Block("", "Genesis Block"));
    }
    void addBlock(string data) {
        Block block(chain.back().hash, data);
        chain.push_back(block);
    }
    void printChain() {
        for(int i = 0; i < chain.size(); i++) {
            cout << "Block " << i << endl;
            cout << "Data: " << chain[i].data << endl;
            cout << "Previous Hash: " << chain[i].prevHash << endl;
            cout << "Hash: " << chain[i].hash << endl;
            cout << endl;
        }
    }
};
int main() {
