tagger.string = text
let options: NSLinguisticTagger.Options = [.omitWhitespace, .omitPunctuation, .joinNames]
var countFigurativeLanguage = 0
tagger.enumerateTags(in: NSRange(text.startIndex..<text.endIndex, in: text), unit: .word, scheme: .lexicalClass, options: options) { tag, tokenRange, _, _ in
    guard let tag = tag else { return }
    let token = String(text[tokenRange])
    switch tag {
    case .noun, .verb, .adjective, .adverb:
        countFigurativeLanguage += checkFigurativeLanguage(token)
    default:
        break
    }
}
func checkFigurativeLanguage(_ token: String) -> Int {
    let figurativeLanguage = ["metaphor", "simile", "personification"]
    for language in figurativeLanguage {
        if token.localizedCaseInsensitiveContains(language) {
            return 1
        }
    }
    return 0
}
