```
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
namespace TextDataCleansing
{
    class Program
    {
        static void Main(string[] args)
        {
            // Sample text data
            string text = "The quick brown fox jumps over the lazy dog. The lazy dog is not amused.";
            // Split the text into individual words
            string[] words = text.Split(new[] { ' ', '.', ',', ';', ':', '-', '!', '?' }, StringSplitOptions.RemoveEmptyEntries);
            // Create a hashset to store unique words
            HashSet<string> uniqueWords = new HashSet<string>();
            // Loop through each word in the text
            foreach (string word in words)
            {
                // Use regular expressions to remove any non-alphanumeric characters
                string cleanedWord = Regex.Replace(word, "[^0-9a-zA-Z]+", "");
                // Check if the cleaned word is already in the hashset
                if (!uniqueWords.Contains(cleanedWord))
                {
                    // If not, add it to the hashset
                    uniqueWords.Add(cleanedWord);
                }
            }
            // Print out the unique words
            Console.WriteLine("Unique words:");
            foreach (string uniqueWord in uniqueWords)
            {
                Console.WriteLine(uniqueWord);
            }
            // Wait for user input before closing the console window
            Console.ReadLine();
        }
    }
}
```
In this example, we start by defining a sample text string and splitting it into individual words using the `Split` method. We then create a `HashSet<string>` to store the unique words we find.
Next, we loop through each word in the text and use regular expressions to remove any non-alphanumeric characters. We then check if the cleaned word is already in the hashset. If it's not, we add it to the hashset.
Finally, we print out the unique words that we found.
This is just a simple example, but you could extend it further by incorporating natural language processing algorithms to identify and remove redundant or irrelevant information.

