The algorithm used to find the shortest path in a graph is Dijkstra's algorithm. This algorithm works by starting at a source node and iteratively exploring the neighboring nodes, updating the shortest distances to each node as it goes. It keeps track of the visited nodes and the shortest distance to each node from the source node. The algorithm terminates when it has visited all nodes or when it has found the shortest path to the target node.
Here is a Java code implementation of Dijkstra's algorithm:
```java
import java.util.*;
public class Dijkstra {
    public static void main(String[] args) {
        int[][] graph = {{0, 4, 0, 0, 0, 0, 0, 8, 0},
                         {4, 0, 8, 0, 0, 0, 0, 11, 0},
                         {0, 8, 0, 7, 0, 4, 0, 0, 2},
                         {0, 0, 7, 0, 9, 14, 0, 0, 0},
                         {0, 0, 0, 9, 0, 10, 0, 0, 0},
                         {0, 0, 4, 14, 10, 0, 2, 0, 0},
                         {0, 0, 0, 0, 0, 2, 0, 1, 6},
                         {8, 11, 0, 0, 0, 0, 1, 0, 7},
                         {0, 0, 2, 0, 0, 0, 6, 7, 0}};
        int source = 0;
        int target = 4;
        int[] distances = dijkstra(graph, source);
        System.out.println("Shortest distance from node " + source + " to node " + target + ": " + distances[target]);
    }
    public static int[] dijkstra(int[][] graph, int source) {
        int n = graph.length;
        int[] distances = new int[n];
        boolean[] visited = new boolean[n];
        Arrays.fill(distances, Integer.MAX_VALUE);
        distances[source] = 0;
        for (int i = 0; i < n - 1; i++) {
            int u = findMinDistance(distances, visited);
            visited[u] = true;
            for (int v = 0; v < n; v++) {
                if (!visited[v] && graph[u][v] != 0 && distances[u] != Integer.MAX_VALUE && distances[u] + graph[u][v] < distances[v]) {
                    distances[v] = distances[u] + graph[u][v];
                }
            }
        }
        return distances;
    }
    public static int findMinDistance(int[] distances, boolean[] visited) {
        int minDistance = Integer.MAX_VALUE;
        int minIndex = -1;
        for (int i = 0; i < distances.length; i++) {
            if (!visited[i] && distances[i] < minDistance) {
                minDistance = distances[i];
                minIndex = i;
            }
        }
        return minIndex;
    }
}
