using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms.DataVisualization.Charting;
namespace BarChartExample
{
    class Program
    {
        static void Main(string[] args)
        {
            // Set data values
            int[] age = { 18, 21, 30, 40, 50 };
            int[] educationLevel = { 12, 16, 18, 20, 24 };
            string[] gender = { "Male", "Female", "Male", "Female", "Male" };
            int[] incomeLevel = { 20000, 30000, 40000, 50000, 60000 };
            // Create chart object
            Chart chart = new Chart();
            // Set chart properties
            chart.Width = 500;
            chart.Height = 500;
            chart.Titles.Add("Age vs Education Level vs Gender vs Income Level");
            chart.ChartAreas.Add(new ChartArea());
            chart.Series.Add(new Series("Age"));
            chart.Series.Add(new Series("Education Level"));
            chart.Series.Add(new Series("Gender"));
            chart.Series.Add(new Series("Income Level"));
