                chart.Series["Education Level"].Points.AddXY(gender[i], educationLevel[i]);
                chart.Series["Gender"].Points.AddXY(age[i], gender[i]);
                chart.Series["Income Level"].Points.AddXY(gender[i], incomeLevel[i]);
