            // Set chart type to bar chart
            chart.Series["Age"].ChartType = SeriesChartType.Bar;
            chart.Series["Education Level"].ChartType = SeriesChartType.Bar;
            chart.Series["Gender"].ChartType = SeriesChartType.Bar;
            chart.Series["Income Level"].ChartType = SeriesChartType.Bar;
            // Set zoom-in and zoom-out feature
            chart.ChartAreas[0].AxisX.ScaleView.Zoomable = true;
            chart.ChartAreas[0].AxisY.ScaleView.Zoomable = true;
            chart.ChartAreas[0].CursorX.IsUserEnabled = true;
            chart.ChartAreas[0].CursorX.IsUserSelectionEnabled = true;
            chart.ChartAreas[0].AxisX.ScaleView.ZoomReset();
            chart.ChartAreas[0].AxisY.ScaleView.ZoomReset();
            chart.ChartAreas[0].AxisX.ScaleView.Zoom(0, 5);
