        private static void ChartArea_AxisZoomChanged(object sender, ViewEventArgs e)
        {
            // Set zoom-in and zoom-out feature
            if (e.Axis.AxisName == AxisName.X)
            {
                double xMin = e.Axis.ScaleView.ViewMinimum;
                double xMax = e.Axis.ScaleView.ViewMaximum;
                ((Chart)sender).ChartAreas[0].AxisX.ScaleView.Zoom(xMin, xMax);
