[C++ code]
int binarySearch(int arr[], int l, int r, int x) {
    while (l <= r) {
        int m = l + (r - l) / 2;

        // Check if x is present at mid
        if (arr[m] == x)
            return m;

        // If x greater, ignore left half
        if (arr[m] < x)
            l = m + 1;

        // If x is smaller, ignore right half
        else
            r = m - 1;
    }

    // if we reach here, then element was not present
    return -1;
}
[Linked List C++ code]
int search(Node* head, int x) {
    // Initialize current
    Node* current = head;

    // Traverse the list
    while (current != NULL) {
        // If x is found at current
        if (current->data == x)
            return 1;

        // Move to next node
        current = current->next;
    }
    // If x is not present
    return -1;
}
