Here's an example of JavaScript code that can handle the quiz functionality:
```
// define the quiz questions and options using an array of objects
const quiz = [
  {
    question: "What is the capital of France?",
    options: ["Paris", "London", "Berlin", "Madrid"],
    answer: "Paris"
  },
  {
    question: "What is the highest mountain in the world?",
    options: ["Mount Everest", "Mount Kilimanjaro", "Mount Fuji", "Mount McKinley"],
    answer: "Mount Everest"
  },
  {
    question: "What is the largest country in the world?",
    options: ["Russia", "China", "United States", "Canada"],
    answer: "Russia"
  }
];
// define variables to keep track of the quiz progress
let currentQuestion = 0;
let score = 0;
// define functions to load the questions and options, check the answers, and display the score
function loadQuestion() {
  const question = document.querySelector("#question");
  const options = document.querySelector("#options");
  question.textContent = quiz[currentQuestion].question;
  options.innerHTML = "";
  quiz[currentQuestion].options.forEach(option => {
    const button = document.createElement("button");
    button.textContent = option;
    button.addEventListener("click", checkAnswer);
    options.appendChild(button);
  });
}
function checkAnswer(event) {
  const selectedAnswer = event.target.textContent;
  if (selectedAnswer === quiz[currentQuestion].answer) {
    score++;
  }
  currentQuestion++;
  if (currentQuestion < quiz.length) {
    loadQuestion();
  } else {
    displayScore();
  }
}
function displayScore() {
  const container = document.querySelector("#container");
  container.innerHTML = "";
  const heading = document.createElement("h2");
  heading.textContent = `Your score is ${score}/${quiz.length}`;
  container.appendChild(heading);
}
// call the loadQuestion function to start the quiz
loadQuestion();
```
